function debounce(fn, wait) {
  let timer = null;
  return (...args) => {
    clearTimeout(timer);                         // cancel the pending call
    timer = setTimeout(() => fn(...args), wait); // start over
  };
}

const search = debounce((q) => console.log("search", q), 300);
search("r"); search("re"); search("rea"); // logs once, 300 ms after "rea"

